-- A person's contact, kept without surrounding spaces and lower-cased; null for none. No two people on a sheet share
-- one. Kept in the person's history too (see V39). The journal trigger is made again around the change, as in V41.
DROP TRIGGER person_journal;
ALTER TABLE person ADD COLUMN contact VARCHAR(255);
ALTER TABLE person_history ADD COLUMN contact VARCHAR(255);
CREATE TRIGGER person_journal AFTER INSERT, UPDATE, DELETE ON person FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.setting.Settings;

/**
 * A person on a sheet. {@code grade} (one of A, B or C) is the first grade they were given, which applies
 * from the beginning of time; {@code dated} are the grades given since, each from its date on, by date.
 * {@code version} is raised on every edit. {@code retiredFrom} is the date they are retired from (null when
 * not retired); a person with one set is retired at once, whatever the date. {@code holds} are their holds, by
 * from-date: their OPEN claims dated within one, unless bound by a statement, count in no live total.
 * {@code terms} are their own terms in days, which come before those of their grade and of the sheet (null for none).
 * {@code contact} is their contact, trimmed and lower-cased (null for none); no two people on a sheet share one.
 * {@code aliases} are their aliases, sorted as names are compared (ignoring case).
 * {@code origin} is the id of the sheet they were transferred from (null when they were not transferred in).
 * {@code retirements} are their past retirements (each ended by unretiring them), by from-date.
 */
public record Person(long id, String sheetId, String name, String grade, long version, LocalDate retiredFrom,
        List<Hold> holds, List<DatedGrade> dated, Integer terms, String contact, List<String> aliases, String origin,
        List<Retirement> retirements) {

    public Person with(PersonRequest request) {
        return new Person(id, sheetId, request.name(), grade, version + 1, retiredFrom, holds, dated,
                request.terms() == null ? null : Integer.valueOf(request.terms()), request.contact(), aliases, origin, retirements);
    }

    /** The grade in force on the date: the one with the latest from-date on or before it, else the first grade. */
    public String gradeOn(LocalDate date) {
        String on = grade;
        for (DatedGrade d : dated) {
            if (!d.from().isAfter(date)) {
                on = d.grade();
            }
        }
        return on;
    }

    /** The terms in force on the date: the person's own, else those of their grade then (else the sheet's). */
    public int termsOn(LocalDate date, Settings settings) {
        return terms != null ? terms : settings.terms(sheetId, gradeOn(date), date);
    }

    /** Whether the person has any hold. */
    public boolean held() {
        return !holds.isEmpty();
    }

    /** Whether the date falls within any of the person's holds. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Whether the person's retirement date is reached on the date (it is on or after it). */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date != null && !date.isBefore(retiredFrom);
    }

    public boolean retired() {
        return retiredFrom != null;
    }
}
package net.officefloor.hq.app.person;

/**
 * The body of an add or an edit of a person: the name as typed and the grade (A, B or C). An edit
 * also names the {@code version} its form loaded (null on an add), and {@code gradeFrom}, the date
 * (yyyy-mm-dd) the grade is given from, blank for the sheet's today. An add's grade is the first one,
 * which applies from the beginning of time, so it ignores {@code gradeFrom}. {@code terms} are the person's own
 * terms, a whole number of days, null (blank) for none. {@code contact} is the person's contact, trimmed and
 * lower-cased, null (blank) for none.
 */
public record PersonRequest(String name, String grade, Long version, String gradeFrom, String terms, String contact) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/**
 * A person as the screen sees it. {@code grade} is the grade in force on the sheet's today; {@code grades} are
 * all the grades they were given, by from-date (yyyy-mm-dd; null for the first, from the beginning of time).
 * {@code retiredFrom} is yyyy-mm-dd, null when not retired; {@code held} is whether they have any
 * hold; {@code holds} are their holds by from-date (yyyy-mm-dd; {@code to} null when it has no end).
 * {@code terms} are their own terms in days, null for none; {@code contact} is their contact, null for none;
 * {@code aliases} are their aliases, sorted as names are compared; {@code clashing} is whether their name or an alias
 * is also a name or alias of someone else on the sheet's tree (see {@link People#clashing}); {@code origin} is the id of
 * the sheet they were transferred from, null when they were not transferred in; {@code retirements} are their past
 * retirements by from-date (yyyy-mm-dd, each to the day they were unretired).
 */
public record PersonResponse(long id, String name, String grade, List<Graded> grades, long version,
        String retiredFrom, boolean held, List<Held> holds, Integer terms, String contact, List<String> aliases, boolean clashing,
        String origin, List<Retired> retirements) {

    public record Graded(String from, String grade) {
    }

    public record Held(String from, String to) {
    }

    public record Retired(String from, String to) {
    }

    public static PersonResponse from(Person person, LocalDate today) {
        return from(person, today, false);
    }

    public static PersonResponse from(Person person, LocalDate today, boolean clashing) {
        List<Graded> grades = new ArrayList<>();
        grades.add(new Graded(null, person.grade()));
        person.dated().forEach(d -> grades.add(new Graded(d.from().toString(), d.grade())));
        return new PersonResponse(person.id(), person.name(), person.gradeOn(today), grades, person.version(),
                person.retiredFrom() == null ? null : person.retiredFrom().toString(), person.held(),
                person.holds().stream().map(h -> new Held(h.from().toString(), h.to() == null ? null : h.to().toString()))
                        .toList(), person.terms(), person.contact(), person.aliases(), clashing, person.origin(),
                person.retirements().stream().map(r -> new Retired(r.from().toString(), r.to().toString())).toList());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {

    // The name is kept without surrounding spaces; a blank one is refused.
    public void validate(@RequestBody PersonRequest body, Out<PersonRequest> request) throws InvalidPersonException {
        request.set(PersonRules.parse(body));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyPerson {
    // Person is a record, so the edited person is published in place of the loaded one. The edit is
    // refused when the version its form loaded is not the stored one: someone else saved it since.
    // The form's grade is given from its from-date (the sheet's today when blank), keeping the grades
    // already given; a save leaving the grade in force today as it is, with no from-date, gives none.
    // The name is refused when anyone else on the sheet's tree uses it as a name or alias.
    public void apply(@Val PersonRequest request, @Val Person person, People people, Sheets sheets,
            Out<PersonResponse> responseOut) throws InvalidPersonException, PersonConflictException {
        if (request.version() != null && request.version() != person.version()) {
            throw new PersonConflictException("Someone else has saved this person since it was opened.");
        }
        if (people.nameTaken(person.sheetId(), request.name(), person.id())) {
            throw new InvalidPersonException("The name is already in use.");
        }
        // A person whose alias clashes across the sheet's tree is refused every edit (only a rename frees the name).
        if (people.aliasClashes(person)) {
            throw new InvalidPersonException("An alias of theirs is already in use on the sheet's tree.");
        }
        if (request.contact() != null && people.contactTaken(person.sheetId(), request.contact(), person.id())) {
            throw new InvalidPersonException("The contact is already in use.");
        }
        LocalDate today = sheets.today(person.sheetId());
        Person edited = person.with(request);
        if (!people.save(edited)) {
            throw new PersonConflictException("Someone else has saved this person since it was opened.");
        }
        if (request.gradeFrom() != null || !request.grade().equals(person.gradeOn(today))) {
            LocalDate from = request.gradeFrom() != null ? LocalDate.parse(request.gradeFrom()) : today;
            people.gradeFrom(person.id(), from, request.grade());
            List<DatedGrade> dated = new ArrayList<>(edited.dated().stream().filter(d -> !d.from().equals(from)).toList());
            dated.add(new DatedGrade(from, request.grade()));
            dated.sort(Comparator.comparing(DatedGrade::from));
            edited = new Person(edited.id(), edited.sheetId(), edited.name(), edited.grade(), edited.version(),
                    edited.retiredFrom(), edited.holds(), List.copyOf(dated), edited.terms(), edited.contact(), edited.aliases(), edited.origin(), edited.retirements());
        }
        responseOut.set(PersonResponse.from(edited, today));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class AddPerson {
    public void add(@Val PersonRequest request, @PathVariable("sheetId") String sheetId, People people,
            Out<Person> personOut) throws InvalidPersonException {
        if (people.nameTaken(sheetId.trim(), request.name(), -1)) {
            throw new InvalidPersonException("The name is already in use.");
        }
        if (request.contact() != null && people.contactTaken(sheetId.trim(), request.contact(), -1)) {
            throw new InvalidPersonException("The contact is already in use.");
        }
        personOut.set(people.add(sheetId.trim(), request));
    }
}
